BEGIN;
CREATE TYPE rebalancing_strategy AS ENUM ('NEW_MONEY','GRADUAL_TRANSFER','COMBINED','MANUAL');
CREATE TYPE rebalancing_status AS ENUM ('DRAFT','APPROVED','ACTIVE','PAUSED','COMPLETED','CANCELLED');
CREATE TABLE money_rebalancing_plans(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,money_case_id bigint NOT NULL REFERENCES money_cases(id) ON DELETE CASCADE,name text NOT NULL,strategy rebalancing_strategy NOT NULL,start_date date NOT NULL,target_date date,review_frequency_months integer CHECK(review_frequency_months BETWEEN 1 AND 120),status rebalancing_status NOT NULL DEFAULT 'DRAFT',created_by bigint NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),approved_at timestamptz,CHECK(target_date IS NULL OR target_date>=start_date));
CREATE TABLE money_rebalancing_targets(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,rebalancing_plan_id bigint NOT NULL REFERENCES money_rebalancing_plans(id) ON DELETE CASCADE,component_code text NOT NULL,starting_allocation_pct numeric(7,4),target_allocation_pct numeric(7,4) NOT NULL,starting_value numeric(18,2),target_value numeric(18,2),priority smallint CHECK(priority BETWEEN 1 AND 5),UNIQUE(rebalancing_plan_id,component_code),CHECK(target_allocation_pct BETWEEN 0 AND 100));
CREATE TABLE money_rebalancing_steps(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,rebalancing_plan_id bigint NOT NULL REFERENCES money_rebalancing_plans(id) ON DELETE CASCADE,sequence_no integer NOT NULL,planned_date date NOT NULL,from_component_code text,to_component_code text,planned_amount numeric(18,2),planned_percentage numeric(7,4),step_type text NOT NULL CHECK(step_type IN ('NEW_CONTRIBUTION','TRANSFER','SELL_BUY','REVIEW_ONLY')),status text NOT NULL DEFAULT 'PLANNED' CHECK(status IN ('PLANNED','APPROVED','EXECUTED','SKIPPED','CANCELLED')),executed_at timestamptz,actual_amount numeric(18,2),notes text,UNIQUE(rebalancing_plan_id,sequence_no));
COMMIT;
